from .core_objects import DataEncoding, FunctionType
from .telegram_field import TelegramField


class DataInformationBlock(TelegramField):
    EXTENSION_BIT_MASK = 0x80  # 1000 0000
    FUNCTION_MASK = 0x30   # 0011 0000
    DATA_FIELD_MASK = 0x0F  # 0000 1111
    MORE_RECORDS_FOLLOW = 0x1F  # 0001 1111

    def __init__(self, parts=None):
        super(DataInformationBlock, self).__init__(parts or [])

    @property
    def has_extension_bit(self):
        """Check for extension bit on last byte"""
        return bool(self.parts and (self.parts[-1] & self.EXTENSION_BIT_MASK))

    @property
    def has_lvar_bit(self):
        """Returns true if the first VIFE has LVAR active"""
        return len(self.parts) > 1 and (self.parts[1] & self.EXTENSION_BIT_MASK) > 0

    @property
    def is_eoud(self):
        """Check for end of user data bit in VIF byte"""
        if not self.parts:
            return False
        return self.parts[0] in {0x0F, 0x1F}

    @property
    def is_manufacturer_specific(self):
        """Check for manufacturer-specific record"""
        return bool(self.parts and self.parts[0] == 0x0F)

    @property
    def more_records_follow(self):
        """Check if more records follow after this block"""
        return bool(self.parts and self.parts[0] == self.MORE_RECORDS_FOLLOW)

    @property
    def function_type(self):
        if not self.parts:
            return FunctionType.UNKNOWN

        dif = self.parts[0]

        if self.is_eoud and self.more_records_follow:
            return FunctionType.MORE_RECORDS_FOLLOW
        elif dif == 0x0F:
            return FunctionType.SPECIAL_FUNCTION
        elif dif == 0x2F:
            return FunctionType.SPECIAL_FUNCTION_FILL_BYTE

        return FunctionType((dif & self.FUNCTION_MASK) >> 4)

    @property
    def is_variable_length(self):
        """Check if the data field has variable length"""
        return bool(self.parts and (self.parts[0] & self.DATA_FIELD_MASK) == 0x0D)

    @property
    def length_encoding(self):
        """Decode length encoding and data encoding from DIF"""
        if not self.parts:
            return 0, DataEncoding.ENCODING_NULL

        len_enc = self.parts[0] & self.DATA_FIELD_MASK

        # Map data field encoding lengths to (length, encoding type)
        length_encoding_map = {
            0: (0, DataEncoding.ENCODING_NULL),
            1: (1, DataEncoding.ENCODING_INTEGER),  # 1 byte int [8 bit]
            2: (2, DataEncoding.ENCODING_INTEGER),  # 2 byte int [16 bit] or date
            3: (3, DataEncoding.ENCODING_INTEGER),  # 3 byte int [24 bit]
            4: (4, DataEncoding.ENCODING_INTEGER),  # 4 byte int [32 bit] or date
            5: (4, DataEncoding.ENCODING_REAL),     # 4 byte float [32 bit]
            6: (6, DataEncoding.ENCODING_INTEGER),  # 6 byte int [48 bit]
            7: (8, DataEncoding.ENCODING_INTEGER),  # 8 byte int [64 bit]
            8: (0, DataEncoding.ENCODING_NULL),     # No data
            9: (1, DataEncoding.ENCODING_BCD),      # 2-digit BCD [8 bit]
            10: (2, DataEncoding.ENCODING_BCD),     # 4-digit BCD [16 bit]
            11: (3, DataEncoding.ENCODING_BCD),     # 6-digit BCD [24 bit]
            12: (4, DataEncoding.ENCODING_BCD),     # 8-digit BCD [32 bit]
            13: (None, DataEncoding.ENCODING_VARIABLE_LENGTH),  # Variable length
            14: (5, DataEncoding.ENCODING_BCD),     # 12-digit BCD [40 bit]
